			WB_out <= WB_in;
			MemWrite <= M_in[1];
			MemRead <= M_in[0];
			ALU_out <= ALU_in;
			RDdata2_out <= RDdata2_in;
			instruction_mux_out <= instruction_mux_in;
		end
	end
endmodule

