module top_module(
  input rst,
  input wr_clk,
  input rd_clk,
  input [N-1:0] din,
  input wr_en,
  input rd_en,
  output [N-1:0] dout,
  output full,
  output empty
);parameter N = 8; // FIFO capacity

  reg [N-1:0] buffer [0:N-1];
  reg [N-1:0] wr_ptr = 0;
  reg [N-1:0] rd_ptr = 0;
  reg [N-1:0] count = 0;
  reg [N-1:0] data_out; // Changed to reg type

  assign dout = data_out;
  assign full = (count == N);
  assign empty = (count == 0);

  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 0;
      count <= 0;
    end
    else if (wr_en && !full) begin
      buffer[wr_ptr] <= din;
      wr_ptr <= (wr_ptr == N-1) ? 0 : wr_ptr + 1;
      count <= count + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr <= 0;
      count <= 0;
      data_out <= 0; // Initialize data_out on reset
    end
    else if (rd_en && !empty) begin
      data_out <= buffer[rd_ptr];
      rd_ptr <= (rd_ptr == N-1) ? 0 : rd_ptr + 1;
      count <= count - 1;
    end
  end

endmodule

