input   [SIZE-1:0]      din ;   
input                   clkl ;  
input                   rst ;   

output  [SIZE-1:0]      q ;     

reg     [SIZE-1:0]      q ;



always @ (negedge clkl or posedge rst)
  q[SIZE-1:0] <= rst ? {SIZE{1'b1}} : din[SIZE-1:0];

endmodule

module decoder_2to4(
	input wire [1:0] A,
	output reg [3:0] Y
);

always @(*) begin
	case (A)
		2'b00: Y = 4'b0001;
		2'b01: Y = 4'b0010;
		2'b10: Y = 4'b0100;
		2'b11: Y = 4'b1000;
		default: Y = 4'b0000;
	endcase
end

endmodule

