module top_module(
  input clk1,
  input clk2,
  input sel,
  output reg clk_out
);reg prev_sel;
  reg prev_clk1;
  reg prev_clk2;

  always @(posedge clk1 or posedge clk2 or posedge sel) begin
    if (sel == 0) begin
      clk_out <= clk1;
    end else begin
      clk_out <= clk2;
    end
    prev_sel <= sel;
    prev_clk1 <= clk1;
    prev_clk2 <= clk2;
  end

  always @(posedge clk_out) begin
    if (prev_sel != sel) begin
      if (sel == 0) begin
        clk_out <= prev_clk1;
      end else begin
        clk_out <= prev_clk2;
      end
    end
    prev_sel <= sel;
    prev_clk1 <= clk1;
    prev_clk2 <= clk2;
  end

endmodule

