description:
Design a 3-bit up/down counter that increments or decrements its count value based on the `up_down` control signal. It includes load functionality, allowing a specific value (`load_val`) to be loaded into the counter when the `load` signal is asserted. The counter resets to zero when the `reset` signal is activated. The counting operation occurs with each positive edge of the clock (`clk`). When `up_down` is high, the counter increments; when low, it decrements.
module top_module(/*AUTOARG*/
   // Outputs
   count,
   // Inputs
   clk, reset, load, up_down,
   load_val
   );

code:
module top_module(/*AUTOARG*/
   // Outputs
   count,
   // Inputs
   clk, reset, load, up_down,
   load_val
   );input clk, reset, load, up_down;
   input [2:0] load_val;

   output reg [2:0] count;

   always @(posedge clk) begin
      if (reset) begin
         count <= 3'b0;
      end
      else if (load) begin
         count <= load_val;
      end
      else begin
         if (up_down) begin
            count <= count + 1;
         end
         else begin
            count <= count - 1;
         end
      end
   end

endmodule

