module top_module (
        input clk,
        input areset,
        input moisture_low,
        input moisture_high,
        output reg sprinkler_on);parameter Off = 1'b0, On = 1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Off;
		else begin
			case (state)
				Off: state <= moisture_low ? On : Off;
				On: state <= moisture_high ? Off : On;
			endcase
		end
	end

	assign sprinkler_on = (state == On);

endmodule

