module top_module(
    input clk,
    input clk_pll,
    input RS232_Rx,
    output RS232_Tx,
    output reg Pulse,
    output reg Sync,
    output reg Block
);reg [24:0] pulse_counter = 0;
reg [24:0] sync_counter = 0;
reg block_active = 0;

// Generate pulse signal with frequency of 1 Hz
always @(posedge clk) begin
    pulse_counter <= pulse_counter + 1;
    if (pulse_counter == 25000000) begin
        pulse_counter <= 0;
        Pulse <= ~Pulse;
    end
end

// Generate sync signal with frequency of 10 Hz
always @(posedge clk) begin
    sync_counter <= sync_counter + 1;
    if (sync_counter == 5000000) begin
        sync_counter <= 0;
        Sync <= ~Sync;
    end
end

// Generate block signal that is high for 1 second after pulse signal is generated
always @(posedge clk) begin
    if (Pulse && !block_active) begin
        block_active <= 1;
        Block <= 1;
    end else if (block_active) begin
        block_active <= 0;
        Block <= 0;
    end
end

// RS232 communication
always @(posedge clk_pll) begin
    // TODO: implement RS232 communication
end

endmodule

