module vending_machine (
	input clk,
	input resetn,
	input coin,
	output dispense);

	parameter IDLE=0, COIN1=1, COIN2=2, DISPENSE=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = coin ? COIN1 : IDLE;
			COIN1: next_state = coin ? COIN2 : COIN1;
			COIN2: next_state = coin ? DISPENSE : COIN2;
			DISPENSE: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign dispense = (state == DISPENSE);
endmodule

