    parallel_out <= 16'b0000000000000000;
  else if (load)
    parallel_out <= parallel_in;
  else if (dir)
    parallel_out <= {parallel_out[14:0], 1'b0};
  else
    parallel_out <= {1'b0, parallel_out[15:1]};
end

endmodule

