module top_module(
  input clk,
  input rst,
  input [127:0] din,
  input wr_en,
  input rd_en,
  output reg [127:0] dout, // Changed wire to reg
  output full,
  output empty,
  input [3:0] prog_full,
  input [3:0] prog_empty
);reg [127:0] fifo_mem [0:14];
reg [3:0] wr_ptr = 0;
reg [3:0] rd_ptr = 0;
wire [3:0] next_wr_ptr = wr_ptr + 1;
wire [3:0] next_rd_ptr = rd_ptr + 1;

wire fifo_full = (next_wr_ptr == rd_ptr);
wire fifo_empty = (wr_ptr == rd_ptr);

assign full = fifo_full;
assign empty = fifo_empty;

reg [3:0] prog_full_reg = prog_full;
reg [3:0] prog_empty_reg = prog_empty;

always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        dout <= 0; // Reset dout on reset
        prog_full_reg <= prog_full;
        prog_empty_reg <= prog_empty;
    end else begin
        if (wr_en && !fifo_full) begin
            fifo_mem[wr_ptr] <= din;
            wr_ptr <= next_wr_ptr;
        end

        if (rd_en && !fifo_empty) begin
            dout <= fifo_mem[rd_ptr];
            rd_ptr <= next_rd_ptr;
        end

        if (prog_full_reg == wr_ptr) begin
            prog_full_reg <= prog_full;
        end else if (fifo_full) begin
            prog_full_reg <= next_wr_ptr;
        end

        if (prog_empty_reg == rd_ptr) begin
            prog_empty_reg <= prog_empty;
        end else if (fifo_empty) begin
            prog_empty_reg <= next_rd_ptr;
        end
    end
end

endmodule

