module top_module(
  input data,
  input clk_src,
  input clk_dst,
  input rst,
  output reg data_sync
);reg data_src;
reg data_dst;
reg sync_pulse;

always @(posedge clk_src, negedge rst) begin
  if (~rst) begin
    data_src <= 1'b0;
  end else begin
    data_src <= data;
  end
end

always @(posedge clk_dst, negedge rst) begin
  if (~rst) begin
    data_dst <= 1'b0;
    sync_pulse <= 1'b0;
  end else begin
    data_dst <= data_src;
    sync_pulse <= 1'b1;
  end
end

always @(posedge clk_dst, negedge rst) begin
  if (~rst) begin
    data_sync <= 1'b0;
  end else begin
    data_sync <= data_dst;
  end
end

endmodule

