description:
Design a UART (Universal Asynchronous Receiver-Transmitter) transmitter module for serial data transmission. The module takes an 8-bit data input and sends it out bit by bit over a single serial output line (ser_out) while managing the transmission state through a busy flag (tx_busy). It uses a clock signal to shift each bit out of a buffer containing the data to be transmitted, while a counter generates timing control signals to synchronize the transmission rate. The module also handles reset conditions to ensure proper initialization and operation.
module top_module(
	clock, reset,
	ce_16, tx_data, new_tx_data, 
	ser_out, tx_busy
);

code:
module top_module(
	clock, reset,
	ce_16, tx_data, new_tx_data, 
	ser_out, tx_busy
);input 			clock;			
input 			reset;			
input			ce_16;			
input	[7:0]	tx_data;		
input			new_tx_data;	
output			ser_out;		
output 			tx_busy;		


wire ce_1;		


reg ser_out;
reg tx_busy;
reg [3:0]	count16;
reg [3:0]	bit_count;
reg [8:0]	data_buf;



always @ (posedge clock or posedge reset)
begin
	if (reset) 
		count16 <= 4'b0;
	else if (tx_busy & ce_16)
		count16 <= count16 + 4'b1;
	else if (~tx_busy)
		count16 <= 4'b0;
end 


assign ce_1 = (count16 == 4'b1111) & ce_16;


always @ (posedge clock or posedge reset)
begin
	if (reset) 
		tx_busy <= 1'b0;
	else if (~tx_busy & new_tx_data)
		tx_busy <= 1'b1;
	else if (tx_busy & (bit_count == 4'h9) & ce_1)
		tx_busy <= 1'b0;
end 


always @ (posedge clock or posedge reset)
begin
	if (reset) 
		bit_count <= 4'h0;
	else if (tx_busy & ce_1)
		bit_count <= bit_count + 4'h1;
	else if (~tx_busy) 
		bit_count <= 4'h0;
end 


always @ (posedge clock or posedge reset)
begin
	if (reset) 
		data_buf <= 9'b0;
	else if (~tx_busy)
		data_buf <= {tx_data, 1'b0};
	else if (tx_busy & ce_1)
		data_buf <= {1'b1, data_buf[8:1]};
end 


always @ (posedge clock or posedge reset)
begin
	if (reset) 
		ser_out <= 1'b1;
	else if (tx_busy)
		ser_out <= data_buf[0];
	else 
		ser_out <= 1'b1;
end 

endmodule

