description:
Design a PWM (Pulse Width Modulation) generator that produces a signal with a frequency of 10 kHz and a configurable duty cycle of 50% based on a 50 MHz clock input. The output, `pwm_out`, toggles between high and low states to create a square wave whose duty cycle is determined by comparing the counter value against a calculated threshold. This module is essential for applications requiring control of power delivered to devices, such as motors or LEDs, by varying the average voltage.
module top_module(
  input clk,
  input ctrl,
  output pwm_out
);

code:
module top_module(
  input clk,
  input ctrl,
  output pwm_out
);parameter f_clk = 50_000_000;  // 50 MHz clock frequency
parameter f_pwm = 10_000;  // 10 kHz PWM frequency
parameter duty_cycle = 50;  // 50% duty cycle

reg [31:0] counter = 0;
reg pwm_out_reg = 0;

always @(posedge clk) begin
  counter <= counter + 1;
  if (counter >= f_clk / f_pwm) begin
    counter <= 0;
    pwm_out_reg <= (counter < (f_clk / f_pwm) * duty_cycle / 100) ? 1 : 0;
  end
end

assign pwm_out = pwm_out_reg;

endmodule

