module top_module(
    input [7:0] A,
    input [7:0] B,
    input [2:0] ctrl,
    input [3:0] in,
    output reg [7:0] out
);reg [7:0] and_out;
reg [7:0] or_out;
reg [7:0] xor_out;
reg [7:0] add_out;
reg [7:0] sub_out;
reg [7:0] mul_out;
reg [7:0] div_out;
reg [7:0] mod_out;

always @* begin
    case(ctrl)
        3'b000: out = A & B;
        3'b001: out = A | B;
        3'b010: out = A ^ B;
        3'b011: out = A + B;
        3'b100: out = A - B;
        3'b101: out = A * B;
        3'b110: out = A / B;
        3'b111: out = A % B;
        default: out = 0;
    endcase
end

always @* begin
    if(ctrl == 3'b011) begin
        add_out = in[0] + in[1];
    end else begin
        add_out = 0;
    end
end

always @* begin
    out = out + add_out;
end

endmodule

module top_module(
    input [15:0] ADC_in, 
    input [15:0] offset, 
    input clk,

    output [15:0] ADC_out,
    output idle_bit
    );reg [15:0] adc_val;
assign ADC_out = adc_val;

reg idle;
assign idle_bit = idle;

always @ (posedge clk)
begin
    idle = 0;

    adc_val = ADC_in + offset;

    idle = 1;
end
endmodule

module xnor_gate(
    input [3:0] a,
    input [3:0] b,
    output [3:0] result
);
    assign result = ~(a ^ b);
endmodule

module binary_updown_counter (
  input clk, 
  input reset, 
  input up, 
  input [3:0] limit, 
  input [3:0] state, 
  output reg [3:0] next_state, 
  output reg [3:0] count, 
  output reg done);parameter IDLE=0, COUNTUP=1, COUNTDOWN=2, DONE=3;

    assign next_state[IDLE] = state[DONE] | (state[IDLE] & reset);
    assign next_state[COUNTUP] = (state[IDLE] & ~reset & up) | (state[COUNTUP] & (count != limit));
    assign next_state[COUNTDOWN] = (state[IDLE] & ~reset & ~up) | (state[COUNTDOWN] & (count != 0));
    assign next_state[DONE] = (state[COUNTUP] & (count == limit)) | (state[COUNTDOWN] & (count == 0));

    always @(posedge clk or posedge reset) begin
        if (reset) 
            count <= 4'b0000;
        else if (state[COUNTUP])
            count <= count + 1;
        else if (state[COUNTDOWN])
            count <= count - 1;
    end

    assign done = state[DONE];

endmodule

